<div class="grid"><section class="card"><div class="card-header"><div><div class="report-section-title">📊 สรุปสมาชิกแยกตามส่วน</div><div class="report-subtitle">ปีงบประมาณ <?= $fy ?><?= $monthIndex?' · '.$monthNames[$monthIndex-1]:' · ทั้งปี' ?></div></div></div><div class="report-table-wrap"><table class="report-table"><thead><tr><th>ส่วนข้อมูล</th><th class="right">รายการ</th><th class="right">สมัครใหม่</th><th class="right">ต่ออายุ</th><th class="right">ยอดสุทธิ</th></tr></thead><tbody><?php foreach($sectionLabels as $key=>$label):$r=$sectionMap[$key]??[];?><tr><td><?= report_e($label) ?></td><td class="right"><?= number_format((int)($r['total']??0)) ?></td><td class="right"><?= number_format((int)($r['new_count']??0)) ?></td><td class="right"><?= number_format((int)($r['renew_count']??0)) ?></td><td class="right"><?= report_money($r['net_revenue']??0) ?></td></tr><?php endforeach;?></tbody></table></div></section><section class="card"><div class="card-header"><div><div class="report-section-title">🎯 ผลงานพนักงาน</div><div class="report-subtitle">ไม่รวมในยอดสมาชิก · ตามตัวกรองที่เลือก</div></div></div><div class="report-table-wrap"><table class="report-table"><tbody><tr><th>จำนวนครั้งปฏิบัติงาน</th><td class="right"><?= number_format($totalWork) ?></td></tr><tr><th>แจ้งข่าวสมาชิก</th><td class="right"><?= number_format($totalNotifications) ?></td></tr><tr><th>ยอดผลงานพนักงาน</th><td class="right"><?= report_money($totalSales) ?></td></tr></tbody></table></div></section></div>
<?php if ($dynamicSummaries): ?><section class="card"><div class="card-header"><div><div class="report-section-title">🧩 รายงานจากหัวข้อ Excel ที่เพิ่มเอง</div><div class="report-subtitle">แสดงจำนวนรายการตามค่าของหัวข้อที่ตั้งค่าไว้ ไม่ตีความเป็นยอดเงินโดยอัตโนมัติ</div></div></div>
<?php foreach($dynamicSummaries as $field): ?><div style="border-top:1px solid #edf1f5;padding-top:16px;margin-top:12px"><div style="font-weight:700;margin-bottom:4px"><?= report_e($field['header_name']) ?></div><div class="report-subtitle">ขอบเขต: <?= report_e($field['section_scope']==='all'?'ทุกหมวด':($sectionLabels[$field['section_scope']]??$field['section_scope'])) ?> · ค่าที่พบบ่อยไม่เกิน 12 รายการ</div>
