<section class="card"><div class="card-header"><div><div class="report-section-title">🏢 สรุปผลงานตามอาคาร</div><div class="report-subtitle">เฉพาะข้อมูลการปฏิบัติงานของพนักงาน</div></div></div><div class="report-table-wrap"><table class="report-table"><thead><tr><th>อาคาร</th><th class="right">ครั้ง</th><th class="right">แจ้งข่าว</th><th class="right">ยอดผลงาน</th></tr></thead><tbody><?php foreach($buildingRows as $r):?><tr><td><?= report_e($r['building']?:'ไม่ระบุ') ?></td><td class="right"><?= number_format((int)$r['work_count']) ?></td><td class="right"><?= number_format((int)$r['notifications']) ?></td><td class="right"><?= report_money($r['sales']) ?></td></tr><?php endforeach;?><?php if(!$buildingRows):?><tr><td colspan="4" style="text-align:center">ยังไม่มีข้อมูลอาคาร</td></tr><?php endif;?></tbody></table></div></section>
<section class="card"><div class="card-header"><div><div class="report-section-title">📋 รายละเอียดรายเดือน</div><div class="report-subtitle">ข้อมูลสมาชิกจาก Excel โดยแยกจำนวนและยอดสุทธิ</div></div></div><div class="report-table-wrap"><table class="report-table"><thead><tr><th>เดือน</th><th class="right">รายการ</th><th class="right">สมัครใหม่</th><th class="right">ต่ออายุ</th><th class="right">ยอดสุทธิ</th></tr></thead><tbody><?php foreach($monthlyRows as $r):?><tr><td><?= report_e($r['month']) ?></td><td class="right"><?= number_format($r['total']) ?></td><td class="right"><?= number_format($r['new']) ?></td><td class="right"><?= number_format($r['renew']) ?></td><td class="right"><?= report_money($r['revenue']) ?></td></tr><?php endforeach;?></tbody></table></div></section>
