const dynamicCanvas<?= (int)$field['id'] ?>=document.getElementById('dynamicFieldChart<?= (int)$field['id'] ?>');if(dynamicCanvas<?= (int)$field['id'] ?>&&typeof Chart!=='undefined')new Chart(dynamicCanvas<?= (int)$field['id'] ?>,{type:'bar',data:{labels:<?= json_encode($field['labels'],JSON_UNESCAPED_UNICODE) ?>,datasets:[{label:'จำนวนรายการ',data:<?= json_encode($field['counts']) ?>,borderWidth:1}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false},tooltip:{callbacks:{label:c=>Number(c.raw||0).toLocaleString('th-TH')+' รายการ'} }},scales:{y:{beginAtZero:true,ticks:{precision:0}}}}});
